  function screenPointer(input){const [w,h]=input.viewport||[1280,720],scale=Math.sqrt(w/1280*h/720);return {x:(input.pointer[0]-w/2)/scale,y:(input.pointer[1]-h/2)/scale};}
  function worldPointer(input){
    const [w,h]=input.viewport||[1280,720],x=camera[0]+(input.pointer[0]/w*2-1)*zoom*w/h,base=camera[1]+(input.pointer[1]/h*2-1)*zoom/sin,map=mode==='editor'?editMap:state.map;
    // Orthographic ray marches down from above the highest authored terrain, finding the front surface.
    let y=6.01,z=base+y*Math.cos(pitch)/sin;
    for(;y>=0;y-=.04){z=base+y*Math.cos(pitch)/sin;if(y<=S.elevation(map,x,z)){let lo=y,hi=y+.04;for(let k=0;k<8;k++){const mid=(lo+hi)/2;if(mid<=S.elevation(map,x,base+mid*Math.cos(pitch)/sin))lo=mid;else hi=mid;}z=base+hi*Math.cos(pitch)/sin;break;}}
    if(y<0)z=base;return {x:S.clamp(x,-30,30),z:S.clamp(z,-30,30)};
  }
  function screenWorld(u,input){const [w,h]=input.viewport||[1280,720],scale=Math.sqrt(w/1280*h/720);return {x:(u.x-camera[0])/zoom*h/2/scale,y:((u.z-camera[1])*sin-(u.y??S.unitHeight(state,u))*Math.cos(pitch))/zoom*h/2/scale};}
